lab.solution:
def completion_percent(completed, total):
    if completed < 0 or total < 0:
        raise ValueError('counts must not be negative')
    if total == 0:
        return 0
    return round(completed / total * 100)

assert completion_percent(3, 4) == 75
assert completion_percent(0, 0) == 0
try:
    completion_percent(-1, 4)
except ValueError:
    pass
else:
    raise AssertionError('negative count should fail')

lab.testCode:
assert completion_percent(3,4) == 75
assert completion_percent(0,0) == 0
assert completion_percent(1,2) == 50
try:
    completion_percent(-1,4)
except ValueError:
    pass
else:
    raise AssertionError('negative completed count accepted')
